// === Tab: mySketch ===
//In honor of my son Rowan and all LGBTQIA+ youth

let font, flag
let restPoints=[]
let balloons=[]
let balloonIndex=0
let dragons=[]
let dragonIndex=0
let dragonCountDown=0
let confettis=[]
let confettiIndex=0
let colors=["#e50000","#ff8d00","#ffee00","#008121","#004cff","#760188"]

function preload() {
  font = loadFont('https://openprocessing.org/sketch/1597460/files/Mukta-ExtraBold.ttf');
	flag= loadImage('https://openprocessing.org/sketch/1597460/files/pride.jpeg');
}

function setup() {
	createCanvas(800, 600);
	textFont(font)
	textAlign(CENTER)
	textSize(100)
	pointsA = font.textToPoints('BE YOU', 220, 100, 100, {
    sampleFactor: 0.1,
    simplifyThreshold: 0
  })
	pointsB = font.textToPoints('BE PROUD', 180, 250, 100, {
    sampleFactor: 0.1,
    simplifyThreshold: 0
  })
	pointsC = font.textToPoints('YOU MATTER', 110, 400, 100, {
    sampleFactor: 0.1,
    simplifyThreshold: 0
  })
	pointers= concat(pointsA, pointsB)
	restPoints= concat(pointers, pointsC)
}

function draw() {
background(255);


if(balloons.length<restPoints.length){
balloons.push(new balloon(balloonIndex))
balloonIndex++
}

for(let balloon of balloons){
	balloon.float();
	balloon.show();
}

	if(balloons.length==restPoints.length){
		dragonCountDown+=1
		if(dragonCountDown%100==0 && dragons.length<6){
			dragons.push(new dragon(dragonIndex))
			dragonIndex+=1
		//	print('fly my pretty')
		}
	}

	for(let dragon of dragons){
		dragon.march();
		dragon.beProud();
	}

	if(frameCount>1570){
		if(frameCount%3==0){
		confettis.push(new confetti(random(25, 125), confettiIndex%6))
		confettis.push(new confetti(width-random(25, 125), confettiIndex%6))
		confettiIndex+=1
		}
	}

	for(let c of confettis){
		c.fall();
		c.flutter();
	}

}


class balloon {
	constructor(index){
		this.pos= createVector(random(width), height+10);
		this.vel= createVector(0, 0);
		this.color= colors[index%6];
		this.acc= createVector(0, 0);
		this.target= createVector(restPoints[index].x, restPoints[index].y)
	}

	float(){
	this.vel.limit(2)
		this.acc.limit(1)
			let force= p5.Vector.sub(this.target, this.pos)
			let r=10
			let d= force.mag();
			if(d<r){
				let m=map(d, 0, r, 0, 1)
				force.setMag(m)
				if(d<=10){
			this.resting=true
			this.targetrest= int(random(10, 150))
			this.seeking=false


			this.acc.setMag(0)
			this.vel.setMag(0)
				}
			}else{
			force.setMag(1)
			}
			this.acc.add(force)

		//this.acc.add(gravity)
		this.vel.add(this.acc);
		this.pos.add(this.vel);

		}	



	show(){
		noStroke()
		fill(this.color)
		ellipse(this.pos.x, this.pos.y, 7, 9)
		ellipse(this.pos.x, this.pos.y+5, 4, 2)
	}
}


class dragon{
	constructor(index){
		this.x=width+100
		this.y=525
		this.color= colors[index]
		this.done=false
		this.targetX= 114+ index*114
	}
	march(){
		if(this.x<=this.targetX){
			this.done=true
		}
		if(!this.done){
			this.x-=1
		}
	}

	beProud(){

		fill(this.color)

		if(!this.done){	
	noStroke()
  let tailPoint= createVector(this.x+50+ (sin(frameCount/20)*30), this.y-50)
  let headPoint=createVector(this.x-40, this.y-40)

  //far legs
  push()
  translate(this.x-20, this.y)
  rotate(sin(frameCount/20)/(PI/2))
  leg()
  fill(0, 30)
  leg()
  pop()

  push()
  translate(this.x+20, this.y)
  rotate(sin(frameCount/20)/(PI/2))
  leg()
  fill(0, 30)
  leg()
  pop()

	//far wing
	wing(this.x+5, this.y+2, 0)
	fill(0, 30)
	wing(this.x+5, this.y+2, 0)

  //tail, body, neck
  fill(this.color)
       beginShape();
		vertex(tailPoint.x, tailPoint.y)

bezierVertex(tailPoint.x, tailPoint.y, this.x+120, this.y, this.x+20, this.y+25);
bezierVertex(this.x+20, this.y+25, this.x-40, this.y+40, this.x-40, this.y);
bezierVertex(this.x-40, this.y, headPoint.x-10, headPoint.y-20, headPoint.x-10, headPoint.y)
  vertex(headPoint.x+10, headPoint.y)
bezierVertex(headPoint.x+10, headPoint.y, this.x-20, this.y-10, this.x, this.y-20 )   
 bezierVertex(this.x+10, this.y-20, this.x+100, this.y+20, tailPoint.x, tailPoint.y)

			endShape();
  //near wing
			wing(this.x, this.y, 0)
			fill(0, 10)
			fill(this.color)
  //near legs
  push()
  translate(this.x-20, this.y)
  rotate(-sin(frameCount/20)/(PI/2))
  leg()
  pop()

  push()
  translate(this.x+20, this.y)
  rotate(-sin(frameCount/20)/(PI/2))
  leg()
  pop()

  //head
  push()
  translate(headPoint.x, headPoint.y)
  rotate(sin(frameCount/20)/20)
  quad(-10, 0, -30, 0, -25, -20, -10, -10)
   quad(10, 0, 28, 0, 25, -20, 10, -10)
  fill(0, 40)
   quad(-10, -5, -30, 0, -25, -20, -10, -10)
   quad(10, -5, 30, 0, 25, -20, 10, -10)
  fill(this.color)
  ellipse(0, 0, 40, 45)
  ellipse(-5, +10, 30, 20)
  fill(0);
  push()
  translate(-8, -5)
  rotate(PI/12)
  ellipse(-1, -2, 6, 10)
  pop()
  push()
  translate(6, -5)
  rotate(-PI/12)
  ellipse(0, -2, 6, 10)
  pop()
  noFill()
  stroke(0)
  arc(-1, +10, 20, 10, 0, PI)
  noStroke()
  fill(0)
  push()
  translate(-3, 4)
  rotate(PI/10)
  ellipse(0, 0, 3, 5)
  pop()
  push()
  translate(3, 4)
  rotate(-PI/10)
  ellipse(0, 0, 3, 5)
  pop()
  pop()



		}else{
			//dragon facing forward holding sign

			ellipse(this.x, this.y, 40, 60)
			push()
			translate(this.x, this.y)
			leg(5, 0)
			wing(5, -5, QUARTER_PI)

			scale(-1, 1)
			leg(5, 0)
			wing(5, -5, QUARTER_PI)
			pop()
			imageMode(CENTER)
			push()
			translate(this.x, this.y)
			rotate(HALF_PI)
			image(flag, 0, 0, 50, 50)
			pop()
	var headPoint= createVector(this.x, this.y-50)	
			push()
  translate(headPoint.x, headPoint.y)
  rotate(sin(frameCount/20)/20)
  quad(-10, 0, -30, 0, -25, -20, -10, -10)
   quad(10, 0, 28, 0, 25, -20, 10, -10)
  fill(0, 40)
   quad(-10, -5, -30, 0, -25, -20, -10, -10)
   quad(10, -5, 30, 0, 25, -20, 10, -10)
  fill(this.color)
  ellipse(0, 0, 40, 45)
  ellipse(-5, +10, 30, 20)
  fill(0);
  push()
  translate(-8, -5)
  rotate(PI/12)
  ellipse(-1, -2, 6, 10)
  pop()
  push()
  translate(6, -5)
  rotate(-PI/12)
  ellipse(0, -2, 6, 10)
  pop()
  noFill()
  stroke(0)
  arc(-1, +10, 20, 10, 0, PI)
  noStroke()
  fill(0)
  push()
  translate(-3, 4)
  rotate(PI/10)
  ellipse(0, 0, 3, 5)
  pop()
  push()
  translate(3, 4)
  rotate(-PI/10)
  ellipse(0, 0, 3, 5)
  pop()
  pop()

	//hands
		stroke(50)
	ellipse(this.x-25, this.y-10, 10, 15)
	ellipse(this.x+25, this.y-10, 10, 15)
			noStroke()
		}
	}

}
function leg(){
  beginShape()
  vertex(-10, 0)
  bezierVertex(-10, 0, 0, -20, 10, 0)
  bezierVertex(10, 0, 0, 40, 10, 40)
  bezierVertex(10, 40, -30, 40, -10, 30)
  endShape()
}

function wing (x, y, r){
	noStroke()
  beginShape();
  push()
  translate(x, y)
  rotate(r)
  vertex(0, 0)
  bezierVertex(0, 0, -30, -60, 0,-45)
  bezierVertex(0, -45, 25, -35, 45, -30)
  bezierVertex(45, -30, 30, -25, 35, -20)
  endShape();
  pop()

}

class confetti{
	constructor(x, index){
		this.x=x
		this.y=-12
		this.r= random(TWO_PI)
		this.size= random(5, 12)
		this.rspeed= random(-2, 2)
		this.colorer= colors[index]
		this.alpha=255
	}
	fall(){
		this.y+=0.8
		this.r+=this.rspeed

		if(this.y>200){
			this.alpha-=2
		}
		if(this.alpha<1){
			let index = confettis.indexOf(this);
      confettis.splice(index, 1);
		}

	}
	flutter(){
		noStroke()
		rectMode(CENTER)
		let filler= color(this.colorer)
		filler.setAlpha(this.alpha)
		fill(filler)
		push()
		translate(this.x, this.y)
		rotate(this.r)
		rect(0, 0, this.size)
		pop()
	}
}

